import{_ as a,o as t,c as i,a2 as l}from"./chunks/framework.CqGS6Fr9.js";const u=JSON.parse('{"title":"Клиент, мод и live","description":"","frontmatter":{"pageId":"developers/client","contentRevision":1},"headers":[],"relativePath":"ru/developers/client.md","filePath":"ru/developers/client.md"}'),r={name:"ru/developers/client.md"};function o(n,e,s,d,c,p){return t(),i("div",null,[...e[0]||(e[0]=[l('<h1 id="клиент-мод-и-live" tabindex="-1">Клиент, мод и live <a class="header-anchor" href="#клиент-мод-и-live" aria-label="Permalink to &quot;Клиент, мод и live&quot;">​</a></h1><p>Применимость: Rimlink 0.8.1 · RimWorld 1.7 · протокол 1.</p><h2 id="usage" tabindex="-1">Как пользоваться <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Как пользоваться {#usage}&quot;">​</a></h2><p>Client.Core: все сетевые вызовы async/cancellable; состояние UI в SharedState; неподтверждённые мутации в outbox. Никаких Verse/RimWorld references. Мод касается игровых объектов только на главном потоке: результаты фоновой работы через MainThread.Post. Harmony patches — по одному на метод с пояснением причины.</p><p>Пешки/предметы передаются ThingBlobs. При входе в мир с возможными совпадающими id нужны newIds:true и ResetMapIndex перед spawn ранее spawned blob. Ссылки на внешние объекты требуют приведения к миру получателя. Pawn equality по thingIDNumber: нельзя Destroy десериализованную копию, равную живой пешке.</p><p>В live зеркало — не самостоятельная симуляция. Coop права на собственных пешек хозяина отличаются от владения привезёнными гостевыми; cleanup не должен возвращать хозяйских пешек почтой.</p><h2 id="limits" tabindex="-1">Ограничения и безопасность <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Ограничения и безопасность {#limits}&quot;">​</a></h2><p>RimWorld 1.7 использует Waylith/CoreCLR, не Unity; UnityEngine — stub. Исследуй реальный тип игры перед предположениями. Локальная сборка и unit tests не заменяют два реальных клиента для игровых изменений.</p><h2 id="related" tabindex="-1">См. также <a class="header-anchor" href="#related" aria-label="Permalink to &quot;См. также {#related}&quot;">​</a></h2><ul><li><a href="./testing">Тестирование и приёмка</a></li><li><a href="./../players/coop">Постоянная совместная колония</a></li><li><a href="./protocol">Протокол и идемпотентность</a></li></ul>',10)])])}const m=a(r,[["render",o]]);export{u as __pageData,m as default};
